// Pure compiled Backend credential/authorization checks. No Host Main, HC assembly or device access.
using System.IO;
using System.Reflection;
using System.Reflection.Emit;
using System.Runtime.Loader;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
internal static class Checks {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 static string testRoot=string.Empty;static Assembly host=null!;static Type backend=null!,optionsType=null!;static readonly List<object> Results=[];static int failed;
 static void Check(bool ok,string name){Results.Add(new{name,ok});if(!ok)failed++;}
 static object Options(string? confirmation,string? session,bool allow=false,string? authorization=null){var o=optionsType.GetMethod("Parse",F)!.Invoke(null,[Array.Empty<string>()])!;optionsType.GetProperty("Confirmation",F)!.SetValue(o,confirmation);optionsType.GetProperty("SessionToken",F)!.SetValue(o,session);optionsType.GetProperty("AllowHardwareWrites",F)!.SetValue(o,allow);optionsType.GetProperty("AuthorizationPath",F)!.SetValue(o,authorization);optionsType.GetProperty("HcAssemblyPath",F)!.SetValue(o,Path.Combine(testRoot,"never-created-hc","HandheldCompanion.dll"));optionsType.GetProperty("HcRuntimeRoot",F)!.SetValue(o,Path.Combine(testRoot,"never-created-hc"));return o;}
 static object Backend(string? c,string? s,bool allow=false,string? auth=null)=>Activator.CreateInstance(backend,F,null,[Options(c,s,allow,auth)],null)!;
 static bool Confirm(object b)=>(bool)backend.GetMethod("HasValidWriteConfirmation",F)!.Invoke(b,null)!;
 static bool Oracle(string? c,string? s)=>!string.IsNullOrWhiteSpace(c)&&!string.IsNullOrWhiteSpace(s)&&CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(c),Encoding.UTF8.GetBytes(s));
 static List<MethodBase> Calls(MethodBase method){var bytes=method.GetMethodBody()!.GetILAsByteArray()!;var rows=new List<MethodBase>();var codes=typeof(OpCodes).GetFields(BindingFlags.Public|BindingFlags.Static).Where(f=>f.FieldType==typeof(OpCode)).Select(f=>(OpCode)f.GetValue(null)!).ToDictionary(x=>(ushort)x.Value);for(int i=0;i<bytes.Length;){ushort id=bytes[i++];if(id==0xfe)id=(ushort)(0xfe00|bytes[i++]);var op=codes[id];if(op.OperandType==OperandType.InlineMethod)rows.Add(method.Module.ResolveMethod(BitConverter.ToInt32(bytes,i))!);i+=op.OperandType switch{OperandType.InlineNone=>0,OperandType.ShortInlineBrTarget or OperandType.ShortInlineI or OperandType.ShortInlineVar=>1,OperandType.InlineVar=>2,OperandType.InlineI8 or OperandType.InlineR=>8,OperandType.InlineSwitch=>4+4*BitConverter.ToInt32(bytes,i),_=>4};}return rows;}
 static string? Rejection(object b){try{backend.GetMethod("EnsureRealWriteAuthorization",F)!.Invoke(b,null);return null;}catch(TargetInvocationException e){return e.InnerException?.GetType().GetProperty("Code",F)?.GetValue(e.InnerException) as string;}}
 static void Dispose(object b)=>((IDisposable)b).Dispose();
 public static int Main(string[] args){
#if FAN_FILE_CONFIG_SELFTEST
  if(args.Length>0&&args[0]=="--file-config")return FanFileConfigChecks.Run(args[1..]);
#endif
try{
  testRoot=Path.GetDirectoryName(Path.GetFullPath(args[1]))!;var dll=Path.GetFullPath(args[0]);var resolver=new AssemblyDependencyResolver(dll);AssemblyLoadContext.Default.Resolving+=(_,n)=>resolver.ResolveAssemblyToPath(n) is {} p?AssemblyLoadContext.Default.LoadFromAssemblyPath(p):null;host=AssemblyLoadContext.Default.LoadFromAssemblyPath(dll);backend=host.GetType("YeManFanHost.RealHcBackend",true)!;optionsType=host.GetType("YeManFanHost.HostOptions",true)!;
  var cases=new List<(string Name,string? Confirmation,string? Session)>{("missing-both",null,null),("missing-confirmation",null,"a"),("missing-session","a",null),("empty-both","",""),("space-both"," "," "),("unicode-space","\u2003","\u2003"),("tab","\t","\t"),("valid-single","a","a"),("case-mismatch","A","a"),("same-length-wrong","a","b"),("suffix-wrong","ab","a"),("leading-space-preserved"," a"," a"),("no-trimming"," a","a"),("canonical-unicode-different","\u00e9","e\u0301"),("embedded-null","a\0b","a\0b"),("replacement-fallback","\ud800","\ud801"),("unicode-cjk","风扇","风扇"),("supplementary","\ud83d\ude00","\ud83d\ude00")};
  foreach(int n in new[]{64,255,256,257,4096}){cases.Add(("valid-length-"+n,new string('a',n),new string('a',n)));cases.Add(("wrong-length-"+n,new string('a',n),new string('b',n)));}
  foreach(var row in cases){var b=Backend(row.Confirmation,row.Session);try{bool expected=Oracle(row.Confirmation,row.Session);Check(Enumerable.Range(0,3).All(_=>Confirm(b)==expected),row.Name+": unchanged current-instance UTF8 comparison");}finally{Dispose(b);}}
  var method=backend.GetMethod("HasValidWriteConfirmation",F)!;var calls=Calls(method);var confirmationField=backend.GetField("writeConfirmationUtf8",F);var sessionField=backend.GetField("writeSessionTokenUtf8",F);
  Check(!calls.Any(x=>x.DeclaringType==typeof(Encoding)&&x.Name=="GetBytes"),"steady confirmation no longer encodes fixed credentials");
  Check(calls.Count(x=>x.DeclaringType==typeof(CryptographicOperations)&&x.Name=="FixedTimeEquals")==1,"each confirmation retains one fixed-time byte comparison");
  foreach(var field in new[]{confirmationField,sessionField})Check(field is not null&&field.IsPrivate&&field.IsInitOnly&&!field.IsStatic&&field.FieldType==typeof(byte[]),"credential encoding is a private readonly per-Backend byte array");
  Check(backend.GetField("options",F)!.IsInitOnly,"Backend retains its readonly immutable options reference");
  foreach(var name in new[]{"Confirmation","SessionToken"})Check(optionsType.GetProperty(name,F)!.SetMethod!.ReturnParameter.GetRequiredCustomModifiers().Any(x=>x.Name=="IsExternalInit"),"HostOptions."+name+" remains init-only");
  var invalid=Backend("wrong","original");try{var c=confirmationField?.GetValue(invalid);var s=sessionField?.GetValue(invalid);Check(!Confirm(invalid),"original invalid configuration rejects before successor construction");var valid=Backend("successor","successor");try{Check(Confirm(valid)&&!Confirm(invalid),"constructing a valid successor cannot authorize the old invalid Backend");if(confirmationField is not null&&sessionField is not null){for(int i=0;i<10;i++)_ = Confirm(invalid);Check(ReferenceEquals(c,confirmationField.GetValue(invalid))&&ReferenceEquals(s,sessionField.GetValue(invalid)),"repeated calls retain the same two encoding objects");Check(!ReferenceEquals(c,confirmationField.GetValue(valid))&&!ReferenceEquals(s,sessionField.GetValue(valid)),"different Backends never share credential buffers");}else {Check(false,"repeated calls retain the same two encoding objects");Check(false,"different Backends never share credential buffers");}}finally{Dispose(valid);}}finally{Dispose(invalid);}
  var auth=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[1]))!,"test-authorization.md");File.WriteAllText(auth,"hardwareWritesAuthorized: true\nallMappedFanRoutesAuthorized: true\n");
  var authorized=Backend("current","current",true,auth);try{backend.GetField("routeOverrideForSelfTest",F)!.SetValue(authorized,backend.GetMethod("ResolveRouteForSelfTest",F)!.Invoke(null,["HandheldCompanion.Devices.GPD.GPDWin5"]));bool CanWrite()=>(bool)backend.GetProperty("CanWrite",F)!.GetValue(authorized)!;
   Check(CanWrite(),"valid current credential and test record still authorize the registered route");File.WriteAllText(auth,"hardwareWritesAuthorized: false\nallMappedFanRoutesAuthorized: false\n");Check(!CanWrite(),"authorization record revocation is still read live");File.Delete(auth);Check(!CanWrite(),"missing authorization record still blocks write");Check(Rejection(authorized)=="REAL_WRITE_AUTH_REQUIRED","missing authorization rejects before any HC load");File.WriteAllText(auth,"hardwareWritesAuthorized: true\nallMappedFanRoutesAuthorized: true\n");Check(CanWrite(),"restoring the test record restores current authorization without another Backend");backend.GetField("routeOverrideForSelfTest",F)!.SetValue(authorized,null);Check(!CanWrite(),"valid credentials cannot authorize an unregistered route");}finally{Dispose(authorized);}
  foreach(var row in new[]{("wrong","current"),("","")}){var b=Backend(row.Item1,row.Item2,true,auth);try{Check(Rejection(b)=="REAL_WRITE_AUTH_REQUIRED","bad confirmation stays rejected before HC/device work");}finally{Dispose(b);}}
  Check(!AppDomain.CurrentDomain.GetAssemblies().Any(x=>x.GetName().Name=="HandheldCompanion"),"no HC assembly loaded");var result=new{ok=failed==0,checks=Results.Count,failed,results=Results,confirmationIl=new{encodingCalls=calls.Count(x=>x.DeclaringType==typeof(Encoding)&&x.Name=="GetBytes"),fixedTimeComparisons=calls.Count(x=>x.DeclaringType==typeof(CryptographicOperations)&&x.Name=="FixedTimeEquals")},hostSha256=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(dll))).ToLowerInvariant(),hardwareCalls=0,cpuBenchmark=false,scope="actual compiled Backend confirmation and live file/registered-route authorization; options constructed with synthetic values before Backend construction, no Host Main/HC/STA/device or CPU/allocation benchmark"};var json=JsonSerializer.Serialize(result);File.WriteAllText(args[1],json);Console.WriteLine(JsonSerializer.Serialize(new{result.ok,result.checks,result.failed,result.confirmationIl}));return failed==0?0:1;
 }catch(Exception e){Console.Error.WriteLine(e);return 2;}}
}

