namespace EvidenceFanAuth {
internal static class FileConfigIoPort {
 private static string root="";private static long reads,exists;
 internal static Action<string>? AfterRead;internal static string? DelayPath;internal static int DelayThread;
 internal static long Reads=>Interlocked.Read(ref reads);internal static long ExistsCalls=>Interlocked.Read(ref exists);
 internal static void Bind(string ownedRoot){if(root.Length!=0)throw new InvalidOperationException("FILE_PORT_ALREADY_BOUND");root=Path.GetFullPath(ownedRoot).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;}
 internal static string Guard(string p){var full=Path.GetFullPath(p);if(!full.StartsWith(root,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("OUTSIDE_OWNED_EVIDENCE");return full;}
 internal static bool Exists(string p){Interlocked.Increment(ref exists);return System.IO.File.Exists(Guard(p));}
 internal static string ReadAllText(string p)=>Read(p,()=>System.IO.File.ReadAllText(p));
 internal static string ReadAllText(string p,Encoding enc)=>Read(p,()=>System.IO.File.ReadAllText(p,enc));
 private static string Read(string p,Func<string> read){Guard(p);Interlocked.Increment(ref reads);var value=read();if(Environment.CurrentManagedThreadId==Volatile.Read(ref DelayThread)&&string.Equals(Path.GetFullPath(p),DelayPath,StringComparison.OrdinalIgnoreCase))AfterRead?.Invoke(p);return value;}
}
}
internal static class FanFileConfigChecks {
 private static readonly List<object> rows=[];private static readonly List<object> observations=[];private static List<string> failures=[];private static int assertions,totalAssertions;private static string root="";private static string tokenA="",tokenB="";
 private const string LegalMd="hardwareWritesAuthorized: true\nallMappedFanRoutesAuthorized: true\n";
 private static void Check(bool ok,string name){assertions++;if(!ok)failures.Add(name);}
 private static string Sha(byte[] b)=>Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();
 private static string ShaText(string s)=>Sha(Encoding.UTF8.GetBytes(s));
 private static string At(string name){var p=Path.Combine(root,name);EvidenceFanAuth.FileConfigIoPort.Guard(p);return p;}
 private static void Seed(string p,byte[] b)=>System.IO.File.WriteAllBytes(p,b);
 private static void Seed(string p,string s)=>Seed(p,new UTF8Encoding(false,true).GetBytes(s));
 private static EvidenceFanAuth.HostOptions Parse(string p)=>EvidenceFanAuth.HostOptions.Parse(["--session-token-file",p]);
 private static bool Matches(string supplied,string? expected)=>EvidenceFanAuth.TokenComparisonSlice.Match(supplied,Encoding.UTF8.GetBytes(expected??""));
 private static EvidenceFanAuth.AuthorizationSlice Backend(string p,bool route=true,string? confirmation=null,bool allow=true)=>new(EvidenceFanAuth.HostOptions.Parse(["--session-token",tokenA]) with {AuthorizationPath=p,AllowHardwareWrites=allow,Confirmation=confirmation??tokenA},route,"HandheldCompanion.Devices.GPDWin5");
 private static Exception? Rejected(Action work){try{work();return null;}catch(Exception ex){return ex;}}
 private static object Outcome(Exception? error)=>new{threw=error!=null,type=error?.GetType().Name};
 private static void Case(string filter,string name,Action run){if(filter.Length>0&&!name.Contains(filter,StringComparison.Ordinal))return;failures=[];assertions=0;var begin=System.Diagnostics.Stopwatch.StartNew();try{run();}catch(Exception ex){failures.Add("unexpected "+ex.GetType().Name);}totalAssertions+=assertions;rows.Add(new{name,ok=failures.Count==0,assertions,failures=failures.ToArray(),elapsedMs=begin.Elapsed.TotalMilliseconds});Console.WriteLine((failures.Count==0?"PASS ":"FAIL ")+name);}
 internal static int Run(string[] args){
  if(args.Length<1)return 2;root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);EvidenceFanAuth.FileConfigIoPort.Bind(root);var filter=args.Length>1?args[1]:"";
  tokenA=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();tokenB=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();
  Case(filter,"file-config/token-legal-and-bom",()=>{var p=At("token-legal.session");Seed(p," \r\n"+tokenA+"\t\n");var o=Parse(p);Check(o.SessionToken==tokenA,"real Parse returns intended token");Check(Matches(tokenA,o.SessionToken),"actual comparator consumes parsed file token");Check(!Matches(tokenB,o.SessionToken),"wrong credential remains refused");Check(!o.AllowHardwareWrites,"token read alone never enables writes");var raw=new byte[]{0xef,0xbb,0xbf}.Concat(Encoding.UTF8.GetBytes(tokenA)).ToArray();Seed(p,raw);Check(Parse(p).SessionToken==tokenA,"legacy UTF8 BOM is accepted");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"reader retains exact original bytes");});
  Case(filter,"file-config/token-missing-empty",()=>{var p=At("token-missing.session");var missing=Rejected(()=>_ = Parse(p));Check(missing!=null,"explicit missing token file cannot random-fallback");foreach(var raw in new[]{Array.Empty<byte>(),Encoding.UTF8.GetBytes(" \r\n\t ")}){Seed(p,raw);Check(Rejected(()=>_ = Parse(p))!=null,"empty token file refuses");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"empty preimage retained");}observations.Add(new{kind="missing-token",error=Outcome(missing)});});
  Case(filter,"file-config/token-invalid-utf8",()=>{var p=At("token-invalid-utf8.session");var raw=new byte[]{0x61,0xff,0x62};Seed(p,raw);EvidenceFanAuth.HostOptions? o=null;var error=Rejected(()=>o=Parse(p));Check(error!=null||string.IsNullOrEmpty(o?.SessionToken),"invalid encoded token must not become a usable loaded credential");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"bad encoding original retained");observations.Add(new{kind="token-invalid-utf8",error=Outcome(error),loadedLength=o?.SessionToken?.Length??0,loadedSha256=o?.SessionToken is{} s?ShaText(s):null,matchesIntendedToken=o is not null&&Matches(tokenA,o.SessionToken),inputSha256=Sha(raw)});});
  Case(filter,"file-config/token-oversize",()=>{var p=At("token-oversize.session");const int limit=4096;var raw=Encoding.ASCII.GetBytes(new string('a',limit+1));Seed(p,raw);EvidenceFanAuth.HostOptions? o=null;var error=Rejected(()=>o=Parse(p));Check(error!=null||string.IsNullOrEmpty(o?.SessionToken),"token file beyond existing frontend 4096-byte budget refuses");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"oversize original retained");observations.Add(new{kind="token-oversize",inputBytes=raw.Length,limit,limitBasis="existing frontend session reader bound, not a new credential format",error=Outcome(error),loadedLength=o?.SessionToken?.Length??0});});
  Case(filter,"file-config/token-sharing-and-explicit-retry",()=>{var p=At("token-sharing.session");Seed(p,tokenA);var before=EvidenceFanAuth.FileConfigIoPort.Reads;Exception? error;using(var held=new FileStream(p,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){error=Rejected(()=>_ = Parse(p));Check(error!=null,"real exclusive file handle refuses token load");Check(EvidenceFanAuth.FileConfigIoPort.Reads-before<=1,"one explicit call does not reread-poll");}var next=Parse(p);Check(next.SessionToken==tokenA,"release plus explicit Parse retries successfully");Check(Matches(tokenA,next.SessionToken),"retried real token reaches actual comparator");Check(System.IO.File.ReadAllText(p)==tokenA,"sharing fault never overwrites token");observations.Add(new{kind="token-sharing",error=Outcome(error)});});
  Case(filter,"file-config/token-replacement-late-read",()=>{var p=At("token-replacement.session");Seed(p,tokenA);using var reached=new ManualResetEventSlim();using var release=new ManualResetEventSlim();EvidenceFanAuth.FileConfigIoPort.DelayPath=Path.GetFullPath(p);EvidenceFanAuth.FileConfigIoPort.AfterRead=_=>{reached.Set();if(!release.Wait(TimeSpan.FromSeconds(3)))throw new TimeoutException("owned read release");};EvidenceFanAuth.HostOptions? old=null;Exception? oldError=null;var late=Task.Run(()=>{Volatile.Write(ref EvidenceFanAuth.FileConfigIoPort.DelayThread,Environment.CurrentManagedThreadId);try{old=Parse(p);}catch(Exception ex){oldError=ex;}});try{Check(reached.Wait(TimeSpan.FromSeconds(3)),"old read reaches real IO result boundary");Seed(p,tokenB);var current=Parse(p);Check(current.SessionToken==tokenB,"new explicit Parse reads replacement");Check(Matches(tokenB,current.SessionToken)&&!Matches(tokenA,current.SessionToken),"new snapshot accepts only its credential");}finally{release.Set();Check(late.Wait(TimeSpan.FromSeconds(3)),"delayed reader completes within bound");EvidenceFanAuth.FileConfigIoPort.DelayThread=0;EvidenceFanAuth.FileConfigIoPort.AfterRead=null;EvidenceFanAuth.FileConfigIoPort.DelayPath=null;}Check(oldError is null&&old?.SessionToken==tokenA,"late result retains original snapshot without guessing new binding");Check(Matches(tokenA,old?.SessionToken)&&!Matches(tokenB,old?.SessionToken),"old options remain old, not silently rebound");Check(System.IO.File.ReadAllText(p)==tokenB,"late reader never writes or rolls back replacement");});
  Case(filter,"file-config/md-live-revoke-missing-restore",()=>{var p=At("authorization-live.md");var legal=LegalMd+"unknown-note: preserved fixture\n";Seed(p,legal);var b=Backend(p);Check(b.Evaluate(),"valid current credential and test record still authorize the bound fake route");Seed(p,"hardwareWritesAuthorized: false\nallMappedFanRoutesAuthorized: false\n");Check(!b.Evaluate(),"authorization record revocation is still read live");System.IO.File.Delete(p);Check(!b.Evaluate(),"missing authorization record still blocks write");Seed(p,legal);Check(b.Evaluate(),"restoring the test record restores current authorization without another consumer");Check(System.IO.File.ReadAllText(p)==legal,"unknown md text remains unchanged");});
  Case(filter,"file-config/md-sharing-and-explicit-retry",()=>{var p=At("authorization-sharing.md");Seed(p,LegalMd);var b=Backend(p);bool granted=false;Exception? error;var before=EvidenceFanAuth.FileConfigIoPort.Reads;using(var held=new FileStream(p,FileMode.Open,FileAccess.ReadWrite,FileShare.None)){error=Rejected(()=>granted=b.Evaluate());Check(!granted,"unreadable md never grants authorization");Check(error is null,"md IO refusal returns safe bool instead of escaping consumer");Check(EvidenceFanAuth.FileConfigIoPort.Reads-before<=1,"one explicit authorization check does not read-poll");}Check(b.Evaluate(),"release plus explicit authorization check recovers");Check(System.IO.File.ReadAllText(p)==LegalMd,"IO refusal preserves md bytes");observations.Add(new{kind="md-sharing",authorizationGranted=granted,error=Outcome(error)});});
  Case(filter,"file-config/md-invalid-utf8",()=>{var p=At("authorization-invalid-utf8.md");var raw=Encoding.UTF8.GetBytes(LegalMd).Concat(new byte[]{0xff}).ToArray();Seed(p,raw);bool granted=false;var error=Rejected(()=>granted=Backend(p).Evaluate());Check(!granted,"invalid UTF8 md cannot grant authorization");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"invalid md preimage retained");observations.Add(new{kind="md-invalid-utf8",authorizationGrantedByPureReader=granted,error=Outcome(error),inputBytes=raw.Length,inputSha256=Sha(raw)});});
  Case(filter,"file-config/md-oversize",()=>{var p=At("authorization-oversize.md");const int limit=1<<20;var raw=Encoding.ASCII.GetBytes(LegalMd+new string('x',limit+1-LegalMd.Length));Seed(p,raw);bool granted=false;var error=Rejected(()=>granted=Backend(p).Evaluate());Check(!granted,"md exceeding bounded config text budget cannot grant authorization");Check(System.IO.File.ReadAllBytes(p).SequenceEqual(raw),"oversize md preimage retained");observations.Add(new{kind="md-oversize",inputBytes=raw.Length,limit,limitBasis="one MiB bounded config text fixture budget; Host has no declared reader cap",authorizationGrantedByPureReader=granted,error=Outcome(error)});});
  Case(filter,"file-config/explicit-argument-and-no-file-default",()=>{var p=At("unused-missing.session");var before=EvidenceFanAuth.FileConfigIoPort.Reads;var explicitArg=EvidenceFanAuth.HostOptions.Parse(["--session-token-file",p,"--session-token",tokenA]);Check(explicitArg.SessionToken==tokenA,"explicit CLI token keeps original precedence");Check(EvidenceFanAuth.FileConfigIoPort.Reads==before,"explicit CLI credential does not read sidecar");var defaults=EvidenceFanAuth.HostOptions.Parse([]);Check(defaults.SessionToken is{Length:64}&&!defaults.AllowHardwareWrites,"no-file default is random credential with writes off");Check(defaults.SessionToken!=tokenA&&defaults.SessionToken!=tokenB,"no-file random default does not impersonate fixture binding");});
  Case(filter,"file-config/bound-fields-remain-closed",()=>{var p=At("authorization-closed.md");Seed(p,LegalMd);Check(!Backend(p,route:false).Evaluate(),"credentials cannot authorize absent bound route");Check(!Backend(p,confirmation:tokenB).Evaluate(),"wrong bound confirmation cannot authorize");Check(!Backend(p,allow:false).Evaluate(),"writes-off field remains authoritative");Check(Backend(p).ConfirmationValid(),"exact original fixed-time confirmation still consumes initial bytes");});
  var forbidden=AppDomain.CurrentDomain.GetAssemblies().Where(a=>a.GetName().Name is{} n&&(n.Contains("HandheldCompanion",StringComparison.OrdinalIgnoreCase)||n=="YeManFanHost")).Select(a=>a.GetName().Name).ToArray();
  if(rows.Count==0)return 2;var failed=rows.Count(x=>(bool)x.GetType().GetProperty("ok")!.GetValue(x)! == false);var runtimeFiles=AppDomain.CurrentDomain.GetAssemblies().Where(a=>!a.IsDynamic&&a.Location.Length>0).Select(a=>new{name=a.GetName().Name,path=a.Location,sha256=Sha(System.IO.File.ReadAllBytes(a.Location))}).ToArray();
  var result=new{status=failed==0?"PASS":"FAIL",ok=failed==0,passed=rows.Count-failed,failed,assertions=totalAssertions,cases=rows,observations,processId=Environment.ProcessId,readCalls=EvidenceFanAuth.FileConfigIoPort.Reads,existsCalls=EvidenceFanAuth.FileConfigIoPort.ExistsCalls,forbiddenAssemblies=forbidden,allBindingsEstablishedBeforeFirstCall=true,actualIO="System.IO.File actual delegate under owned-root guard; delayed result timing only",hostMainCalls=0,serverConstructions=0,listenerCalls=0,hcCalls=0,hardwareCalls=0,networkCalls=0,credentialLogging="synthetic fixture only; lengths/hashes/categories, never values or prefixes",runtimeFiles};System.IO.File.WriteAllText(Path.Combine(root,"result.json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{result.status,result.passed,result.failed,result.assertions,result.processId}));return failed==0?0:1;
 }
}
